import React from 'react';
import './Experience.css';

function Experience() {
  const experiences = [
    {
      role: 'Program Mentor',
      organization: 'GCU Women in Business',
      period: 'September 2024 – Present',
      achievements: [
        'Coordinate structured program for 4 participants, tracking milestones, deliverables, and professional development goals',
        'Maintain accurate participant records and documentation, monitoring individual progress and identifying growth opportunities',
        'Facilitate cross-functional collaboration on group projects, ensuring alignment on objectives, timelines, and resources',
        'Provide guidance on business strategy and professional development to strengthen participant outcomes'
      ]
    },
    {
      role: 'Member Services & Pro Shop Attendant',
      organization: 'Hawthorn Woods Country Club',
      period: 'May 2022 – August 2024',
      achievements: [
        'Managed 200+ member accounts and processed 100+ daily transactions across POS, membership database, and event booking systems',
        'Supported execution of 20+ member events, assisting with setup logistics, staffing coordination, and day-of operations',
        'Assisted in training 3 new employees on operational procedures, system workflows, and customer service protocols'
      ]
    }
  ];

  return (
    <section id="experience" className="experience">
      <h2>Professional Timeline</h2>

      <div className="timeline">
        {experiences.map((exp, index) => (
          <div key={index} className="timeline-item">
            <div className="timeline-marker"></div>
            <div className="timeline-content">
              <div className="timeline-header">
                <h3>{exp.role}</h3>
                <span className="timeline-period">{exp.period}</span>
              </div>
              <p className="timeline-org">{exp.organization}</p>
              <ul className="timeline-achievements">
                {exp.achievements.map((achievement, idx) => (
                  <li key={idx}>{achievement}</li>
                ))}
              </ul>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}

export default Experience;
